import re, pathlib
root = pathlib.Path('.')
notes = {p.stem for p in root.rglob('*.md')}
imgs = {p.name for p in root.rglob('*.png')}
words = 0
broken = []
for p in sorted(root.rglob('*.md')):
    txt = p.read_text(encoding='utf-8')
    words += len(txt.split())
    body = re.sub(r'`[^`]*`', '', txt)
    for m in re.findall(r'\[\[([^\]|]+)\]\]', body):
        note, _, head = m.partition('#')
        note = note.strip()
        if note and note not in notes and note not in imgs:
            broken.append((p.name, m))
        elif head:
            tgt = next((q for q in root.rglob('*.md') if q.stem == note), None)
            if tgt and f"# {head.strip()}" not in tgt.read_text(encoding='utf-8'):
                broken.append((p.name, m + "  <- heading missing"))
print("files:", len(notes), "| words:", words)
print("broken:", broken if broken else "none")
PY

