/* AutoImplants evidence console — Index theme.
   Drafting surface at night: void black, carbon panels, 1px dashed containment,
   one rationed periwinkle for annotation. No shadows, no glows, no blur.

   Three notes where an evidence console pulls against the reference:

   1. FAIL is an inverted block — white fill, void text — not a red one. The
      system permits nothing beyond achromatic plus periwinkle, and inverting is
      louder on this canvas than any hue would be. PASS carries a periwinkle dot,
      SKIP stays hatched. The status word is always present as text besides.
   2. Display weight is 900, not the reference's 1000: no web-available grotesque
      reaches 1000, and the reference itself allows a weight axis of >= 900.
   3. Data stays left-aligned and dense. The dashed border does the containment
      work the reference asks of it; the numbers keep their scan order. */

:root {
  /* --- palette ------------------------------------------------------------ */
  --void:        #000000;
  --carbon:      #1c1c1c;
  --graphite:    #4d4d4d;
  --steel:       #808080;
  --ash:         #ababab;
  --paper:       #ffffff;
  --periwinkle:  #7089ba;

  --carbon-2:    #131313;
  --carbon-3:    #242424;

  --dash: 1px dashed var(--graphite);
  --dash-soft: 1px dashed #2e2e2e;

  --font-sans: 'Inter', 'Raveo', 'Manrope', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --font-display: var(--font-sans);
  --font-mono: 'JetBrains Mono', 'Geist Mono', ui-monospace, 'Cascadia Mono', Consolas, monospace;

  --page: 1200px;
  --pad: clamp(20px, 4vw, 40px);
  --sec-gap: clamp(56px, 7vw, 80px);

  --r-badge: 0px;
  --r-card: 0px;
  --r-pill: 100px;

  /* --- tokens the canvas and the sparklines read (see js/theme.js) --------- */
  --viz-bg:      #000000;
  --viz-bone:    #4d4d4d;
  --viz-plate:   #ffffff;
  --viz-edge:    #ababab;
  --viz-gap-ok:  #4d4d4d;
  --viz-gap-bad: #ffffff;
  --viz-accent:  #7089ba;
  --viz-text:    #ffffff;
  --viz-muted:   #808080;
  --viz-faint:   #2e2e2e;
  --viz-line:    #ababab;
  --viz-pass:    #7089ba;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; scroll-padding-top: 80px; }

body {
  margin: 0;
  background: var(--void);
  color: var(--paper);
  font-family: var(--font-sans);
  font-weight: 400;
  font-size: 16px;
  line-height: 1.6;
  letter-spacing: -.16px;
  -webkit-font-smoothing: antialiased;
}

/* The moving background lives in a canvas painted by js/bg.js and sits behind
   everything. These two layers are its static floor: the carbon wash the
   reference calls a desk lamp on a drafting surface, and nothing else. */
#bg-canvas {
  position: fixed; inset: 0; z-index: -2;
  width: 100%; height: 100%; display: block; pointer-events: none;

=== theme.js ===
/* Colours the canvas and the SVG sparklines need, read from the stylesheet.
 *
 * Everything drawn outside the DOM -- the three.js scene, the sparkline strokes --
 * would otherwise hard-code hexes and drift out of the theme the moment the
 * stylesheet changed. These read the CSS custom properties instead, so swapping
 * the <link> in index.html restyles the 3D view and the charts too.
 *
 * Fallbacks are real values, not placeholders: if the stylesheet fails to load,
 * the viewer must still draw a legible scene rather than a black square. */

const FALLBACK = {
  '--viz-bg': '#05060f',
  '--viz-bone': '#3f4959',
  '--viz-plate': '#d1e4fa',
  '--viz-edge': '#98c0ef',
  '--viz-gap-ok': '#5b6577',
  '--viz-gap-bad': '#e46d4c',
  '--viz-accent': '#b6d9fc',
  '--viz-text': '#d8ecf8',
  '--viz-muted': '#9da7ba',
  '--viz-faint': '#3f4959',
  '--viz-line': '#c7d3ea',
  '--viz-pass': '#269684',
};

function read(name) {
  try {
    const v = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
    if (v) return v;
  } catch (_) { /* no document, or the property is not set */ }
  return FALLBACK[name];
}

/** Resolved once at module load: the stylesheet is not going to change mid-session. */
export const viz = Object.freeze({
  bg: read('--viz-bg'),
  bone: read('--viz-bone'),
  plate: read('--viz-plate'),
  edge: read('--viz-edge'),
  gapOK: read('--viz-gap-ok'),
  gapBad: read('--viz-gap-bad'),
  accent: read('--viz-accent'),
  text: read('--viz-text'),
  muted: read('--viz-muted'),
  faint: read('--viz-faint'),
  line: read('--viz-line'),
  pass: read('--viz-pass'),
});

=== bg.js head ===
/* Moving background: a drafting surface drifting under a desk lamp.
 *
 * Worth stating plainly, because it is a departure: the Index style reference
 * this theme follows has NO animated background. Its own guidance calls the
 * aesthetic "deliberately static and architectural" and forbids glows and blur.
 * So the motion here is built only out of primitives the system already owns --
 * dashed rules, achromatic fills, a rationed periwinkle for data nodes -- and it
 * moves slowly enough to read as drift rather than animation.
 *
 * Turn it off with  <body data-bg="off">  or by honouring reduced motion, which
 * it does on its own: that case paints a single static frame and stops.
 */

const CFG = {
  cell: 96,            // dashed grid pitch, px
  dash: [4, 4],        // the reference's 4-on / 4-off
  drift: 5.0,          // px per second, diagonal
  nodes: 14,           // periwinkle data nodes
  nodeSpeed: 5.5,      // px per second
  linkDist: 190,       // px, below which two nodes are joined by a dashed rule
  fps: 30,
};

function css(name, fallback) {
  try {
    const v = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
    if (v) return v;
  } catch (_) { /* fall through */ }
  return fallback;
}

export function startBackground(canvas) {
  if (!canvas || !canvas.getContext) return null;
  const ctx = canvas.getContext('2d', { alpha: true });
  if (!ctx) return null;

  const still = document.body.dataset.bg === 'off'
    || window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  const colors = {
    grid: css('--viz-faint', '#2e2e2e'),
    node: css('--viz-accent', '#7089ba'),
    lamp: css('--carbon', '#1c1c1c'),
  };

input.content:
/* AutoImplants evidence console — CT theme.
   A diagnostic workstation, not a website. The reference is a radiology reading
   room: a calibrated cool-black monitor, bone rendered bright against soft
   tissue, measurements annotated in a single cyan, and every viewport cornered
   by reticle ticks.

   Built as a layer over index-theme.css rather than a fourth full stylesheet.
   The class surface and the --viz-* contract are already correct there; what a
   CT reading room changes is the palette, the type, and the chrome around a
   viewport. Overriding those three is honest about how much is actually
   different, and it cannot drift out of sync with the base.

   Four notes where this pulls against a normal dark UI:

   1. BONE IS THE BRIGHTEST THING ON SCREEN. In CT, density maps to luminance —
      cortical bone is white, soft tissue is mid-grey, air is black. The plate is
      the only object allowed to out-bright it, because it is titanium and would
      genuinely read brighter than bone on a real scan.
   2. FOUR STATUS COLOURS SURVIVE THE PALETTE. One accent is the rule for
      decoration; status is data encoding, not decoration. PASS / FAIL / SKIP /
      ERROR must stay separable at a glance and separable in greyscale, so they
      differ in luminance and in fill pattern, not only in hue.
   3. SKIP IS HATCHED AND DIM ON PURPOSE. Eight stress checks return SKIP today.
      A SKIP that reads as a pass would make this interface lie, so it is drawn
      as absence: no fill, diagonal hatch, dimmer than anything measured.
   4. THE SCANLINE IS FIXED, NEVER SCROLLED. Grain and scanlines on a scrolling
      container force a GPU repaint on every frame. It sits on one fixed,
      pointer-events:none layer and costs nothing. */

@import url('index-theme.css');

:root {
  /* --- palette: a calibrated reading-room monitor -------------------------- */
  /* Never #000: a true black clips the low end and kills the sense of a
     backlit panel. This is the cool near-black a DICOM viewer actually shows. */
  --void:        #06080b;
  --carbon:      #0e1319;
  --carbon-2:    #0a0e13;
  --carbon-3:    #141b23;
  --graphite:    #2b343f;
  --steel:       #5b6875;
  --ash:         #97a4b2;
  --paper:       #e8edf2;

  /* Bone: warm ivory. Everything else on this page is cool, so the one warm
     value in the system is the anatomy — which is what the eye should find. */
  --bone:        #ddd3c2;
  --bone-dim:    #8d8577;

  /* The single accent. Cyan is what measurement annotation is drawn in on a
     diagnostic display, and it is the one hue that never collides with the
     warm bone or with any of the four status colours. */
  --periwinkle:  #58b7c9;
  --cyan-dim:    #2d6f7c;

  /* Status. Desaturated so they sit in the same room as the greys, separated
     in luminance so they survive a greyscale print or a projector. */
  --st-pass:     #4f9d84;
  --st-fail:     #d4614f;
  --st-skip:     #46525f;
  --st-error:    #d9a04b;

  --dash: 1px solid var(--graphite);
  --dash-soft: 1px solid #1a222c;

  /* Geist for the interface, JetBrains Mono for every numeral. A serif or a
     humanist grotesque would both be wrong on a clinical readout. */
  --font-sans: 'Geist', 'Satoshi', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --font-display: var(--font-sans);
  --font-mono: 'JetBrains Mono', 'Geist Mono', ui-monospace, 'Cascadia Mono', Consolas, monospace;

  --r-badge: 0px;
  --r-card: 2px;
  --r-pill: 2px;

  /* --- the tokens js/theme.js and js/bg.js read --------------------------- */
  --viz-bg:      #06080b;
  --viz-bone:    #ddd3c2;
  --viz-plate:   #f4f8fb;
  --viz-edge:    #58b7c9;
  --viz-gap-ok:  #2d6f7c;
  --viz-gap-bad: #d4614f;
  --viz-accent:  #58b7c9;
  --viz-text:    #e8edf2;
  --viz-muted:   #97a4b2;
  --viz-faint:   #1a222c;
  --viz-line:    #97a4b2;
  --viz-pass:    #4f9d84;
}

/* ============================================================================
   THE SCAN SURFACE
   One fixed layer, painted once, never scrolled. Scanlines at 3px pitch plus a
   vignette — the two artifacts that read unmistakably as a medical display.
   ========================================================================== */

body::after {
  content: '';
  position: fixed;
  inset: 0;
  z-index: 40;
  pointer-events: none;
  background:
    repeating-linear-gradient(
      to bottom,
      rgba(255, 255, 255, 0.016) 0px,
      rgba(255, 255, 255, 0.016) 1px,
      transparent 1px,
      transparent 3px
    ),
    radial-gradient(
      ellipse 120% 80% at 50% 45%,
      transparent 55%,
      rgba(2, 4, 7, 0.55) 100%
    );
}

@media (prefers-reduced-motion: reduce) {
  body::after { background: none; }
}

/* ============================================================================
   RETICLE CORNERS
   A DICOM viewport is cornered, not bordered. Four L-shaped ticks read as a
   calibrated frame where a full rectangle would read as a card.
   ========================================================================== */

.viewer,
.minviewer {
  position: relative;
  border: var(--dash-soft);
  background:
    linear-gradient(var(--graphite), var(--graphite)) 0 0 / 14px 1px no-repeat,
    linear-gradient(var(--graphite), var(--graphite)) 0 0 / 1px 14px no-repeat,
    linear-gradient(var(--graphite), var(--graphite)) 100% 0 / 14px 1px no-repeat,
    linear-gradient(var(--graphite), var(--graphite)) 100% 0 / 1px 14px no-repeat,
    linear-gradient(var(--graphite), var(--graphite)) 0 100% / 14px 1px no-repeat,
    linear-gradient(var(--graphite), var(--graphite)) 0 100% / 1px 14px no-repeat,
    linear-gradient(var(--graphite), var(--graphite)) 100% 100% / 14px 1px no-repeat,
    linear-gradient(var(--graphite), var(--graphite)) 100% 100% / 1px 14px no-repeat,
    var(--viz-bg);
}

/* The viewport HUD is a readout, not a caption: mono, tight, uppercase. */
.viewer__hud,
.minviewer__caption {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--ash);
}

.hud-title {
  color: var(--periwinkle);
  letter-spacing: .14em;
}

/* ============================================================================
   TYPE
   Display stays heavy and tight. Everything numeric is monospaced so columns
   of measurements align on the decimal without a table hack.
   ========================================================================== */

.display {
  letter-spacing: -.03em;
  font-weight: 800;
}

.eyebrow,
.section-title,
.pane-title,
.stat__k,
.verdict,
.tag,
.legend__item,
.cmdbox__label {
  font-family: var(--font-mono);
  letter-spacing: .1em;
  text-transform: uppercase;
}

.section-title { color: var(--periwinkle); }

.val,
.unit,
.delta,
.stat__v,
.cell-v,
.bar__ratio,
.dhf__sha,
.trustrow__sha,
.diff,
.rx__json { font-family: var(--font-mono); }

/* A measured value is the most important text on the page. */
.stat__v { font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
.val     { font-variant-numeric: tabular-nums; }

/* ============================================================================
   STATUS
   Hue plus luminance plus fill pattern. Any one of the three can be lost —
   colour-blind viewer, greyscale projector, bad room light — and the remaining
   two still separate the four states.
   ========================================================================== */

.tag--pass,  .swatch--pass  { background: var(--st-pass);  color: #04120d; }
.tag--fail,  .swatch--fail  { background: var(--st-fail);  color: #150300; }
.tag--error, .swatch--error { background: var(--st-error); color: #150d00; }

/* SKIP is drawn as absence: no fill, hatched, and dimmer than any measurement. */
.tag--skip, .swatch--skip {
  background:
    repeating-linear-gradient(
      45deg,
      var(--st-skip) 0px, var(--st-skip) 2px,
      transparent 2px, transparent 5px
    );
  color: var(--ash);
  border: 1px solid var(--st-skip);
}

.bar--pass .bar__fill { background: var(--st-pass); }
.bar--fail .bar__fill { background: var(--st-fail); }
.bar--skip .bar__fill {
  background:
    repeating-linear-gradient(
      45deg,
      var(--st-skip) 0px, var(--st-skip) 2px,
      transparent 2px, transparent 5px
    );
}
.bar__track { background: var(--carbon-2); border: var(--dash-soft); }
.bar__gate  { background: var(--periwinkle); }

.val--fail  { color: var(--st-fail); }
.val--none  { color: var(--st-skip); }
.cell-v--fail { color: var(--st-fail); }
.cell-v--skip { color: var(--st-skip); }
.delta--good { color: var(--st-pass); }
.delta--bad  { color: var(--st-fail); }

.verdict[data-state="fail"] { background: var(--st-fail); color: #150300; }
.verdict[data-state="pass"] { background: var(--st-pass); color: #04120d; }

.stat--alert .stat__v { color: var(--st-fail); }
.stat--skip  .stat__v { color: var(--st-skip); }

/* ============================================================================
   SURFACES
   Panels are windows onto data, so they get a hairline and a slightly lifted
   ground — never a shadow. A drop shadow on a diagnostic display is a lie about
   where the light is.
   ========================================================================== */

.section { border-top: var(--dash-soft); }
.section--hero { border-top: none; }

.checktable thead th {
  background: var(--carbon-2);
  border-bottom: 1px solid var(--graphite);
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: .1em;
  color: var(--ash);
}

.checktable tbody tr:hover { background: rgba(88, 183, 201, 0.045); }
.row--fail { background: rgba(212, 97, 79, 0.07); }

.nav {
  background: rgba(6, 8, 11, 0.82);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--graphite);
}

.wordmark { letter-spacing: -.02em; }
.wordmark__reg { color: var(--periwinkle); }

/* ============================================================================
   CONTROLS
   Tactile feedback on press. A control that does not move under the cursor
   reads as disabled on a panel this dark.
   ========================================================================== */

.pill, .ghost-btn {
  border-radius: var(--r-pill);
  font-family: var(--font-mono);
  letter-spacing: .08em;
  text-transform: uppercase;
  transition: transform .12s cubic-bezier(.16, 1, .3, 1),
              border-color .18s ease,
              background-color .18s ease;
}
.pill:hover, .ghost-btn:hover { border-color: var(--periwinkle); }
.pill:active, .ghost-btn:active { transform: translateY(1px); }

.pill--solid { background: var(--periwinkle); color: #041014; border-color: var(--periwinkle); }
.pill--solid:hover { background: #6ac6d7; }

.pill:focus-visible,
.ghost-btn:focus-visible,
select:focus-visible,
input:focus-visible {
