/* ============================================================================
   MOBILE
   The console is a wide instrument. Below the tablet breakpoint it collapses to
   a single column rather than scrolling sideways.
   ========================================================================== */

@media (max-width: 767px) {
  .split, .split--even, .rx__split { grid-template-columns: 1fr; }
  .nav__links { display: none; }
  .viewer { min-height: 60vh; }
}

/* The main menu, defined once.
 *
 * It used to be hand-written into the <header> of all three pages, which meant
 * adding a section was three edits and forgetting one was a dead link that only
 * showed up by clicking. The nav is now data: edit MENU below and every page
 * picks it up.
 *
 * Two rules this encodes, because they are easy to lose in hand-written markup:
 *
 *   - The current page is marked aria-current="page" and is NOT a link to
 *     itself. A nav that lets you navigate to where you already are reads as
 *     broken on the second click.
 *   - In-page anchors only render on the page that owns them. Linking #geometry
 *     from the prescription page would scroll to nothing.
 */

/** The pages. `anchors` are in-page sections, rendered only on their own page. */
export const MENU = [
  {
    id: 'menu',
    file: 'index.html',
    label: 'MENU',
    short: '← MENU',
    anchors: [],
  },
  {
    id: 'console',
    file: 'console.html',
    label: 'CONSOLE',
    anchors: [
      { hash: '#checks',      label: 'CHECKS' },
      { hash: '#geometry',    label: 'GEOMETRY' },
      { hash: '#timeline',    label: 'TIMELINE' },
      { hash: '#code',        label: 'CODE' },
      { hash: '#trust',       label: 'TRUST' },
      { hash: '#history',     label: 'HISTORY' },
    ],
  },
  {
    id: 'acquisition',
    file: 'prescription.html',
    label: 'ACQUISITION',
    anchors: [
      { hash: '#source',      label: 'CT SOURCE' },
      { hash: '#parameters',  label: 'PARAMETERS' },
      { hash: '#fixed',       label: 'FIXED INPUTS' },
    ],
  },
];

/** Which page is being rendered, from the filename. Defaults to the menu. */
export function currentPageId() {
  const file = (location.pathname.split('/').pop() || 'index.html').toLowerCase();
  const hit = MENU.find((p) => p.file.toLowerCase() === file);
  return hit ? hit.id : 'menu';
}

function el(tag, cls, text) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text != null) n.textContent = text;
  return n;
}

/**
 * Render the links into a container.
 *
 * Order is: back to the menu, this page's own sections, then the other pages.
 * Sections first because once you are on a page, its sections are what you
 * actually reach for; the cross-page links are the rarer move.
 */
export function renderNav(container, pageId = currentPageId()) {
  if (!container) return;
  container.textContent = '';

  const page = MENU.find((p) => p.id === pageId);

  if (pageId !== 'menu') {
    const back = el('a', 'nav__link nav__link--back', '← MENU');
    back.href = 'index.html';
    container.appendChild(back);
  }

  for (const a of (page?.anchors ?? [])) {
    const link = el('a', 'nav__link nav__link--anchor', a.label);
    link.href = a.hash;
    container.appendChild(link);
  }

  for (const p of MENU) {
    if (p.id === pageId || p.id === 'menu') continue;
    const link = el('a', 'nav__link', p.label);
    link.href = p.file;
    container.appendChild(link);
  }

  // The page you are on, marked and inert.
  if (pageId !== 'menu') {
    const here = el('span', 'nav__link nav__link--here', page.label);
    here.setAttribute('aria-current', 'page');
    container.appendChild(here);
  }
}

/** Highlight the section currently on screen. No scroll listener — see below. */
export function trackSections(container) {
  const anchors = [...container.querySelectorAll('.nav__link--anchor')];
  if (!anchors.length || !('IntersectionObserver' in window)) return () => {};

  const byId = new Map(anchors.map((a) => [a.getAttribute('href').slice(1), a]));
  const sections = [...byId.keys()]
    .map((id) => document.getElementById(id))
    .filter(Boolean);
  if (!sections.length) return () => {};

  // IntersectionObserver rather than a scroll handler: a scroll listener fires
  // on every frame and forces layout when it reads offsets.
  const seen = new Set();
  const io = new IntersectionObserver(
    (entries) => {
      for (const e of entries) {
        if (e.isIntersecting) seen.add(e.target.id);
        else seen.delete(e.target.id);
      }
      const top = sections.find((s) => seen.has(s.id));
      for (const [id, a] of byId) a.classList.toggle('is-active', !!top && id === top.id);
    },
    { rootMargin: '-72px 0px -55% 0px', threshold: 0 },
  );

  sections.forEach((s) => io.observe(s));
  return () => io.disconnect();
}

/** Wire the nav on any page: render, then track. */
export function mountNav(selector = '.nav__links') {
  const container = document.querySelector(selector);
  if (!container) return;
  renderNav(container);
  trackSections(container);
}

