/* Minimal STL reader -- binary and ASCII, no loader dependency.
 *
 * The exported solid is what the validators measure, so the viewer reads the
 * same file rather than a converted copy: whatever is drawn here is the artefact
 * that was graded. */

import * as THREE from 'three';

const cache = new Map();

function isBinary(buffer) {
  /* The reliable test is arithmetic, not the "solid" prefix: a binary STL is
   * exactly 84 + 50n bytes, and some ASCII writers start with "solid" too. */
  if (buffer.byteLength < 84) return false;
  const view = new DataView(buffer);
  const tris = view.getUint32(80, true);
  return 84 + tris * 50 === buffer.byteLength;
}

function parseBinary(buffer) {
  const view = new DataView(buffer);
  const tris = view.getUint32(80, true);
  const positions = new Float32Array(tris * 9);
  const normals = new Float32Array(tris * 9);

  for (let i = 0; i < tris; i++) {
    const base = 84 + i * 50;
    const nx = view.getFloat32(base, true);
    const ny = view.getFloat32(base + 4, true);
    const nz = view.getFloat32(base + 8, true);
    for (let v = 0; v < 3; v++) {
