/** Fetch an STL and return a BufferGeometry, or throw. Results are cached: the
 *  bone mesh is shared by every viewer on the page. */
export async function loadSTL(url) {
  if (cache.has(url)) return cache.get(url);

  const promise = (async () => {
    const res = await fetch(url, { cache: 'no-store' });
    if (!res.ok) throw new Error(url + ' -> HTTP ' + res.status);
    const buffer = await res.arrayBuffer();

    const data = isBinary(buffer)
      ? parseBinary(buffer)
      : parseASCII(new TextDecoder().decode(buffer));

    if (!data.positions.length) throw new Error(url + ' contained no triangles');

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(data.positions, 3));
    if (data.normals.length === data.positions.length) {
      geo.setAttribute('normal', new THREE.BufferAttribute(data.normals, 3));
    } else {
      geo.computeVertexNormals();
    }
    geo.computeBoundingBox();
    geo.computeBoundingSphere();
    geo.userData.triangles = data.positions.length / 9;
    return geo;
  })();

  cache.set(url, promise);
  return promise;
}

