 *   this project — there is no code path from a scan to a design. A file picked
 *   here is parsed and drawn locally so you can look at it. It is not uploaded,
 *   not written anywhere, and not graded.
 *
 * So the interface says PREVIEW ONLY in the one place it cannot be missed — on
 * the viewport itself — rather than in a footnote. An input that looks like it
 * feeds the loop, on a project whose entire claim is that the loop cannot be
 * fooled, would be the worst possible thing for this page to imply.
 *
 * Two file classes, treated differently because they genuinely are:
 *
 *   MESH (.stl)   — parsed fully and rendered. This is the same format and the
 *                   same parser the validators read, so what you see is what a
 *                   verifier would measure.
 *   SCAN (.dcm)   — the header is read for acquisition parameters. The pixel
 *                   data is NOT reconstructed: one DICOM file is one slice, a
 *                   reconstruction needs the series plus a segmentation step
 *                   this repository does not have. Showing a fake 3D model from
 *                   a header would be a lie of exactly the kind the verifier
 *                   exists to prevent.
 */

import * as THREE from 'three';
import { geometryFromSTL } from './stl.js';

/* --------------------------------------------------------------- DICOM -- */

/** Tags worth surfacing, as "group,element" -> label. */
const DICOM_TAGS = {
  '0008,0060': 'Modality',
  '0008,0070': 'Manufacturer',
  '0018,0050': 'Slice thickness',
  '0018,0060': 'kVp',
  '0018,1151': 'Tube current',
  '0020,0013': 'Instance number',
  '0028,0010': 'Rows',
  '0028,0011': 'Columns',
  '0028,0030': 'Pixel spacing',
  '0028,1050': 'Window centre',
  '0028,1051': 'Window width',
};

/** Explicit-VR little endian only — the transfer syntax a CT export uses. */
const HAS_LONG_LENGTH = new Set(['OB', 'OW', 'OF', 'SQ', 'UT', 'UN']);

/**
 * Read a DICOM header. Returns null when the file is not DICOM.
 *
 * Deliberately shallow: walk top-level elements until the pixel data, collect
 * the tags above, stop. No decompression, no windowing, no reconstruction.
 */
export function readDicomHeader(buffer) {
  const view = new DataView(buffer);
  if (buffer.byteLength < 132) return null;

  // 128-byte preamble, then the literal "DICM".
  const magic = String.fromCharCode(
    view.getUint8(128), view.getUint8(129), view.getUint8(130), view.getUint8(131),
  );
  if (magic !== 'DICM') return null;

  const out = {};
  const dec = new TextDecoder('latin1');
  let off = 132;

  while (off + 8 <= buffer.byteLength) {
    const group = view.getUint16(off, true);
    const element = view.getUint16(off + 2, true);
    const vr = String.fromCharCode(view.getUint8(off + 4), view.getUint8(off + 5));

    let length;
    let valueOff;
    if (HAS_LONG_LENGTH.has(vr)) {
      length = view.getUint32(off + 8, true);
      valueOff = off + 12;
    } else {
      length = view.getUint16(off + 6, true);
      valueOff = off + 8;
    }

    // Pixel data: everything interesting is behind us, and we do not decode it.
    if (group === 0x7fe0 && element === 0x0010) break;
    if (length === 0xffffffff || valueOff + length > buffer.byteLength) break;

    const key = `${group.toString(16).padStart(4, '0')},${element.toString(16).padStart(4, '0')}`;
    if (DICOM_TAGS[key]) {
      let value;
      if (vr === 'US') value = String(view.getUint16(valueOff, true));
      else if (vr === 'UL') value = String(view.getUint32(valueOff, true));
      else value = dec.decode(new Uint8Array(buffer, valueOff, length)).replace(/\0+$/, '').trim();
      if (value) out[DICOM_TAGS[key]] = value;
    }

    off = valueOff + length + (length % 2); // elements are even-length padded
  }

  return Object.keys(out).length ? out : { Modality: 'unknown' };
}

/* ----------------------------------------------------------------- mesh -- */

/** Millimetre extents and triangle count, the numbers that decide plausibility. */
export function meshStats(geometry) {
  const b = geometry.boundingBox;
  const size = new THREE.Vector3();
  b.getSize(size);
  return {
    triangles: geometry.userData.triangles || geometry.attributes.position.count / 3,
    size: { x: size.x, y: size.y, z: size.z },
    min: { x: b.min.x, y: b.min.y, z: b.min.z },
    max: { x: b.max.x, y: b.max.y, z: b.max.z },
    longestAxis: Math.max(size.x, size.y, size.z),
  };
}

/**
 * Sanity checks, phrased as advisories rather than verdicts.
 *
 * This page grades nothing — only the verifier does that. But a mesh in metres,
 * or one whose long axis is not Z, will silently produce a nonsense preview, and
 * saying so here costs nothing. The wording stays advisory on purpose: these are
 * observations about the file, not check results.
 */
export function meshAdvisories(stats) {
  const notes = [];
  const L = stats.longestAxis;

  if (L < 20) {
    notes.push(['SCALE', `Longest axis is ${L.toFixed(1)} mm. If this was exported in metres or centimetres it needs rescaling — the pipeline works in millimetres throughout.`]);
  } else if (L > 900) {
    notes.push(['SCALE', `Longest axis is ${L.toFixed(0)} mm, longer than any human long bone. Check the export units.`]);
  }

  const { x, y, z } = stats.size;
  if (z < x || z < y) {
    notes.push(['FRAME', 'The longest extent is not +Z. The pipeline expects +Z along the shaft, +X lateral (the mounting aspect), +Y across. A mesh in another frame would place the plate somewhere else entirely.']);
  }

  if (stats.triangles > 200000) {
    notes.push(['DENSITY', `${stats.triangles.toLocaleString()} triangles. Ray casts run per check and per iteration, so a mesh this dense would want decimating to roughly 20k first.`]);
  }

  if (!notes.length) {
    notes.push(['PLAUSIBLE', `${stats.triangles.toLocaleString()} triangles, ${L.toFixed(0)} mm along its longest axis, oriented along +Z. Consistent with a cropped long-bone segment.`]);
  }
  return notes;
}

/* ----------------------------------------------------------------- read -- */

const MESH_EXT = /\.stl$/i;
const SCAN_EXT = /\.(dcm|dicom|ima)$/i;

/**
 * Read one picked file into something the page can display.
 *
 * Resolves to `{kind, name, bytes, geometry?, stats?, advisories?, header?}`.
 * `kind` is 'mesh' | 'scan' | 'unsupported'; it never throws for an unsupported
 * file, because a thrown error would surface as a broken page rather than as
 * the honest answer, which is that this repository cannot read that format.
 */
export async function readFile(file) {
  const buffer = await file.arrayBuffer();
  const base = { name: file.name, bytes: file.size };

  if (MESH_EXT.test(file.name)) {
    try {
      const geometry = geometryFromSTL(buffer);
      const stats = meshStats(geometry);
      return { ...base, kind: 'mesh', geometry, stats, advisories: meshAdvisories(stats) };
    } catch (err) {
      return { ...base, kind: 'unsupported', error: String(err.message || err) };
    }
  }

  // Sniff rather than trust the extension: DICOM files are routinely extensionless.
  const header = readDicomHeader(buffer);
  if (header || SCAN_EXT.test(file.name)) {
    return { ...base, kind: 'scan', header: header || {} };
  }

  return {
    ...base,
    kind: 'unsupported',
    error: 'Not an STL, and no DICM marker at byte 128. NIfTI (.nii) and NRRD are not read here.',
  };
}

/** Human-readable byte size. Mono digits make these align in a column. */
export function formatBytes(n) {
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${(n / 1024 / 1024).toFixed(1)} MB`;
}

