/* ------------------------------------------------------- CT source intake -- */

import { readFile, formatBytes } from './acquisition.js';
import { Viewer } from './viewer.js';

const acq = { viewer: null };

function acqEl(tag, cls, text) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text != null) n.textContent = text;
  return n;
}

function acqRow(host, k, v, mod) {
  host.append(acqEl('div', 'acq__k', k));
  host.append(acqEl('div', 'acq__v' + (mod ? ' acq__v--' + mod : ''), v));
}

/** Lazily built: no point constructing a WebGL context until a file arrives. */
function acqViewer() {
  if (!acq.viewer) {
    acq.viewer = new Viewer(document.getElementById('acq-canvas'), { autoRotate: true });
  }
  return acq.viewer;
}

function showOverlay(text) {
  const o = document.getElementById('acq-overlay');
  if (!o) return;
  o.textContent = text || '';
  o.hidden = !text;
}

async function onFile(file) {
  if (!file) return;
  const meta = document.getElementById('acq-meta');
  meta.replaceChildren();
  showOverlay('READING ' + file.name.toUpperCase() + '…');

  let res;
  try {
    res = await readFile(file);
  } catch (err) {
    showOverlay('');
    acqRow(meta, 'ERROR', String(err.message || err), 'fail');
    return;
  }

  acqRow(meta, 'FILE', res.name);
  acqRow(meta, 'SIZE', formatBytes(res.bytes));

  if (res.kind === 'mesh') {
    showOverlay('');
    const v = acqViewer();
    v.setBone(res.geometry);
    v.frameAll();

    const s = res.stats;
    acqRow(meta, 'KIND', 'SEGMENTED MESH — PARSED AND DRAWN');
    acqRow(meta, 'TRIANGLES', s.triangles.toLocaleString());
    acqRow(meta, 'EXTENT', `${s.size.x.toFixed(1)} × ${s.size.y.toFixed(1)} × ${s.size.z.toFixed(1)} mm`);
    acqRow(meta, 'Z RANGE', `${s.min.z.toFixed(1)} → ${s.max.z.toFixed(1)} mm`);
    for (const [k, note] of res.advisories) acqRow(meta, k, note, k === 'PLAUSIBLE' ? 'ok' : 'warn');

  } else if (res.kind === 'scan') {
    // Deliberately no 3D: one slice is not a volume, and this repository has no
    // segmentation step. Inventing a surface here would be the exact failure the
    // verifier exists to make impossible.
    showOverlay('HEADER READ — PIXEL DATA NOT RECONSTRUCTED');
    acqRow(meta, 'KIND', 'DICOM SLICE — HEADER ONLY');
    for (const [k, v] of Object.entries(res.header)) acqRow(meta, k.toUpperCase(), v);
    acqRow(meta, 'NOT DONE',
      'Reconstruction needs the full series plus a segmentation step. Segmentation is out of '
      + 'scope for this repository, so no surface is derived from this file.', 'warn');

  } else {
    showOverlay('UNREADABLE');
    acqRow(meta, 'KIND', 'UNSUPPORTED', 'fail');
    acqRow(meta, 'WHY', res.error, 'fail');
  }

  acqRow(meta, 'PIPELINE',
    'Not consumed. The loop reads the committed inputs/bone.stl, and nothing here changes that.',
    'warn');
}

function wireAcquisition() {
  const input = document.getElementById('file');
  const drop = document.getElementById('drop');
  if (!input || !drop) return;

  input.addEventListener('change', () => onFile(input.files[0]));

  for (const type of ['dragenter', 'dragover']) {
    drop.addEventListener(type, (e) => { e.preventDefault(); drop.classList.add('is-over'); });
  }
  for (const type of ['dragleave', 'drop']) {
    drop.addEventListener(type, (e) => { e.preventDefault(); drop.classList.remove('is-over'); });
  }
  drop.addEventListener('drop', (e) => onFile(e.dataTransfer?.files?.[0]));

  showOverlay('NO FILE LOADED');
}

wireAcquisition();
